```go
package bookstore

import "sort"

// discounts per group size (1-5 books)
var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
	c := counts[:]

	// Group counts: g5 = c5, g4 = c4-c5, ...
	g5 := c[4]
	g4 := c[3] - c[4]
	g3 := c[2] - c[4]
	g2 := c[1] - c[4]
	g1 := c[0] - c[4]

	cost := g5*discounts[5] + g4*discounts[4] + g3*discounts[3] + g2*discounts[2] + g1*discounts[1]

	// A group of 5 plus a group of 3 costs 5160, but can be regrouped as two
	// groups of 4 for 5120, saving 40 per pair.
	pairs := g5
	if g3 < pairs {
		pairs = g3
	}
	cost -= pairs * 40
	return cost
}
```

