package bookstore

import "sort"

// discounts holds the total cost, in cents, of a group of 0-5 different
// books: no discount for one book, 5% for two, 10% for three, 20% for four
// and 25% for all five.
var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the total cost, in cents, of the books in the basket,
// grouped to give as big a discount as possible.
func Cost(books []int) int {
	counts := [5]int{}
	for _, b := range books {
		counts[b-1]++
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	// Lay the books out in rows: row r holds one copy of every title of
	// which there are at least r. The rows are naturally the groups, and
	// because the counts are sorted, the row sizes are non-increasing:
	// g5 full sets of five, then the leftover rows of four, three, ...
	g5 := counts[4]
	g4 := counts[3] - counts[4]
	g3 := counts[2] - counts[3]
	g2 := counts[1] - counts[2]
	g1 := counts[0] - counts[1]

	cost := g5*discounts[5] + g4*discounts[4] + g3*discounts[3] + g2*discounts[2] + g1*discounts[1]

	// A group of five and a group of three cost 5160 together, but the same
	// eight books can be split into two groups of four for 5120, saving 40
	// per pair. (Two of each of three titles plus one of the remaining two
	// always partitions into two sets of four.)
	if g5 < g3 {
		cost -= g5 * 40
	} else {
		cost -= g3 * 40
	}
	return cost
}

package main

import (
	"fmt"
	"os"
)

var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// fast: the implemented solution (row decomposition + (5,3)->(4,4) fix)
func fast(counts [5]int) int {
	c := [5]int{}
	// sort descending
	for i := 0; i < 5; i++ {
		for j := i + 1; j < 5; j++ {
			if c[j] > c[i] {
				c[i], c[j] = c[j], c[i]
			}
		}
	}
	copy(c, counts)
	g5 := c[4]
	g4 := c[3] - c[4]
	g3 := c[2] - c[3]
	g2 := c[1] - c[2]
	g1 := c[0] - c[1]
	cost := g5*discounts[5] + g4*discounts[4] + g3*discounts[3] + g2*discounts[2] + g1*discounts[1]
	if g5 < g3 {
		cost -= g5 * 40
	} else {
		cost -= g3 * 40
	}
	return cost
}

// exact: memoized DP over the labeled count vector; a move picks any
// non-empty subset of titles with remaining copies (one group).
var memo = map[[5]int]int{}

func exact(c [5]int) int {
	if v, ok := memo[c]; ok {
		return v
	}
	best := 0
	for mask := 1; mask < 32; mask++ {
		size := 0
		ok := true
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				if c[t] == 0 {
					ok = false
					break
				}
				size++
			}
		}
		if !ok {
			continue
		}
		n := c
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				n[t]--
			}
		}
		if v := discounts[size] + exact(n); v > best {
			best = v
		}
	}
	memo[c] = best
	return best
}

func main() {
	maxTotal := 14
	bad := 0
	total := 0
	var worst [5]int
	worstDiff := 0
	// enumerate all count vectors with sum <= maxTotal
	var rec func(c [5]int, rem int)
	rec = func(c [5]int, rem int) {
		total++
		f, e := fast(c), exact(c)
		if f != e {
			bad++
			diff := f - e
			if diff > worstDiff {
				worstDiff = diff
				worst = c
			}
			if bad < 20 {
				fmt.Printf("MISMATCH counts=%v fast=%d exact=%d\n", c, f, e)
			}
		}
		for t := 0; t < 5; t++ {
			if c[t] < maxTotal {
				c[t]++
				rec(c, rem)
				c[t]--
			}
		}
	}
	rec([5]int{}, maxTotal)
	fmt.Printf("checked %d count vectors, %d mismatches (worst diff %d at %v)\n", total, bad, worstDiff, worst)
	if bad > 0 {
		os.Exit(1)
	}
}

