package bookstore

// Temporary verification file (deleted after use): compares Cost against an
// exact memoized DP over count vectors for every basket of up to 22 books.

import (
	"sort"
	"testing"
)

const inf = 1 << 30

var bruteDiscounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

var bruteMemo = map[[5]int]int{}

// bruteExact is the exact optimum: pick any non-empty subset of titles that
// still have copies (one group), recurse, minimize total cost.
func bruteExact(c [5]int) int {
	if v, ok := bruteMemo[c]; ok {
		return v
	}
	if c == ([5]int{}) {
		return 0
	}
	best := inf
	for mask := 1; mask < 32; mask++ {
		size := 0
		ok := true
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				if c[t] == 0 {
					ok = false
					break
				}
				size++
			}
		}
		if !ok {
			continue
		}
		n := c
		for t := 0; t < 5; t++ {
			if mask&(1<<t) != 0 {
				n[t]--
			}
		}
		if v := bruteDiscounts[size] + bruteExact(n); v < best {
			best = v
		}
	}
	bruteMemo[c] = best
	return best
}

func TestBruteForceAgreement(t *testing.T) {
	maxTotal := 22
	checked := 0
	var rec func(c [5]int, rem int)
	rec = func(c [5]int, rem int) {
		checked++
		basket := []int{}
		for b, n := range c {
			for i := 0; i < n; i++ {
				basket = append(basket, b+1)
			}
		}
		sort.Ints(basket)
		got := Cost(basket)
		want := bruteExact(c)
		if got != want {
			t.Fatalf("Cost(%v) = %d, exact optimum %d", basket, got, want)
		}
		for b := 0; b < 5; b++ {
			if rem > 0 {
				c[b]++
				rec(c, rem-1)
				c[b]--
			}
		}
	}
	rec([5]int{}, maxTotal)
	t.Logf("checked %d count vectors (all baskets up to %d books)", checked, maxTotal)
}

